import{_ as n,l as r,o as e,c as l,v as o,p as s,x as i,d as p,i as E,S as d}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"全支付拍卖","description":"","frontmatter":{"title":"全支付拍卖","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/all-pay-auction.md","filePath":"econ/all-pay-auction.md","lastUpdated":1789023840000}'),c={name:"econ/all-pay-auction.md"};function B(h,a,A,m,_,u){const t=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=o('<h1 id="全支付拍卖" tabindex="-1">全支付拍卖 <a class="header-anchor" href="#全支付拍卖" aria-label="Permalink to &quot;全支付拍卖&quot;">​</a></h1><div class="epigraph"><p>每人按自己的报价付钱，只有最高者得到奖赏；游说、竞赛与军备是同一场拍卖，输家的支出并不退回。</p><footer>—— Baye, Kovenock and de Vries, The All-Pay Auction with Complete Information, Economic Theory, 1996；Rigging the Lobbying Process, American Economic Review, 1993</footer></div><p><a href="/econ/winner-curse">上一课</a>把「赢」写成关于共同价值的坏消息，叫价要预先扣减。缺口换成支付规则：不必有共同价值，也可以把钱烧光——游说献金、专利竞赛、晋级考试，所有人支付自己的投入，只有一名赢家。本课钉全支付拍卖，不重写关联与联动，也不把价格发现写成连续簿。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>完全信息、\\(n\\) 人，奖赏 \\(v\\)（可非对称 \\(v_i\\)）。每人同时选支出 \\(x_i\\ge 0\\)，最高者得奖，<strong>所有人支付各自的</strong> \\(x_i\\)。两人对称时，纯策略纳什空：若对方出 \\(x\\)，自己或略高、或出 \\(0\\)；双方都「略高」不可能。混合均衡：支出在 \\([0,v]\\) 上有连续分布，使对手无差异。</p><p>期望总支出可以等于 \\(v\\)（完全耗散），也可以在非对称时小于 \\(v\\)（弱者很少跟，强者省钱）。Baye–Kovenock–de Vries 给出完全信息下均衡集与耗散公式：弱者的参与把强者的租金压住，但强者仍保有正期望支付。</p><h3 id="不是一价-也不是消耗战的时钟" tabindex="-1">不是一价，也不是消耗战的时钟 <a class="header-anchor" href="#不是一价-也不是消耗战的时钟" aria-label="Permalink to &quot;不是一价，也不是消耗战的时钟&quot;">​</a></h3><p>一价只赢家付钱；全支付人人付钱。消耗战把支出写成等待时间，结构同构（连续时间两人消耗战 \\(\\simeq\\) 全支付），但本课用一次同时叫价，便于接到竞赛。赢家诅咒是信息；全支付是会计——即使 IPV 或完全信息，输家也不退款。</p><p><span class="marginnote">Hillman–Riley 把政治竞赛写成全支付；Tullock 的比率竞赛（赢率 \\(\\propto x_i^R\\)）是平滑版，纯策略常存在。全支付是 \\(R\\to\\infty\\) 的极限：最大支出者以概率一获胜。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：完全信息、不可分奖赏、线性成本。两人对称：混合 cdf \\(F(x)=x/v\\) 于 \\([0,v]\\)，期望支付为零。非对称 \\(v_1\\gt v_2\\)：弱者在 \\([0,v_2]\\) 上混合，强者在同一区间混合但在 \\(0\\) 处有原子（正概率出 \\(0\\)）。不完全信息 IPV 全支付：对称递增 \\(b(v)\\)，遮挡比一价更狠，因为付款不再以赢为条件。</p>',11)),(e(),s(d,null,{default:i(()=>[E(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20WC%5B%22%E8%B5%A2%E5%AE%B6%E8%AF%85%E5%92%92%EF%BC%9A%E8%B5%A2%E6%9B%B4%E6%96%B0%E4%BB%B7%E5%80%BC%22%5D%20--%3E%20AP%5B%22%E5%85%A8%E6%94%AF%E4%BB%98%EF%BC%9A%E4%BA%BA%E4%BA%BA%E4%BB%98%E9%92%B1%22%5D%0A%20%20AP%20--%3E%20MIX%5B%22%E5%AE%8C%E5%85%A8%E4%BF%A1%E6%81%AF%EF%BC%9A%E6%B7%B7%E5%90%88%20%2F%20%E8%80%97%E6%95%A3%22%5D%0A%20%20AP%20--%3E%20CON%5B%22%E7%AB%9E%E8%B5%9B%E3%80%81%E6%B8%B8%E8%AF%B4%E3%80%81%E5%86%9B%E5%A4%87%22%5D%0A%20%20AP%20--%3E%20DA%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E4%B8%A4%E8%BE%B9%E5%90%8C%E6%97%B6%E5%87%BA%E4%BB%B7%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>主办方若关心耗散而非配置，可以把奖赏故意给弱者、或公开 handicap，利用非对称压低总支出。这与「提高竞争强度」的直觉相反，但是全支付会计。</p><p>收入（主办方收到的总支出）在完全信息对称时等于奖赏；设计竞赛的人关心耗散，不关心「有效配置」——奖赏往往不可分，配置规则就是最高努力者得。IPV 对称时，全支付的递增均衡把几乎整段估值都变成支出：低类型出接近 \\(0\\)，高类型仍远低于 \\(v\\)，因为付款无条件。主办方收到的期望仍可由后课包络对齐，但选手体验是「输了钱也没回来」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>无差异再次出现：多花 \\(dx\\) 提高赢率，但 \\(dx\\) 一定付出，无论输赢。一价里 \\(dx\\) 只在赢的时候付，所以遮挡较薄。全支付把成本做成沉没，均衡要么混合（完全信息），要么把叫价压到远低于估值（IPV）。耗散是租金的去向：社会剩余变成支出，若支出本身无社会价值（纯游说），福利低于把奖赏直接交给指定者。</p><p>非对称是设计工具。Baye 等「操纵游说」：故意让强者更强，可以降低总耗散——弱者不跟，强者不必烧那么多。这与「公平竞争提高努力」的直觉相反，却是全支付会计的直接结果。</p><h3 id="ipv-全支付与收入等价" tabindex="-1">IPV 全支付与收入等价 <a class="header-anchor" href="#ipv-全支付与收入等价" aria-label="Permalink to &quot;IPV 全支付与收入等价&quot;">​</a></h3><p>对称 IPV、风险中性、最高估值者赢、最低类型支付为零时，全支付的期望收入仍可以对齐一价 / 二价——后课收入等价已经把支付钉在 \\(Q\\) 上。本课完全信息分支不走那条包络：类型公开，混合把租金耗在支出里，不是信息租金。</p><p><span class="marginnote">预算约束、头奖与参与奖、多人取前 \\(k\\)，会改变耗散。实验里全支付常过度支出，与混合无差异难实施有关，不是定义要求「必须亏钱」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>努力有外部社会价值（研发）时，耗散不全是浪费。动态、多阶段竞赛、全支付加共同价值，诅咒与沉没支出叠在一起，本课不混写。也不要把全支付写成限价簿的吃单——这里没有对手方队列。</p><p>完全信息混合在实验里难实施：无差异对任意密度成立，受试者往往过度支出。设计含义仍成立——奖赏越大、越对称，耗散越狠。要把努力当社会产出，需改支付（部分报销、参与奖），不是改成「鼓励公平竞争」一句话。</p><p>后课默认：全支付是人人付款的竞赛；完全信息靠混合，IPV 靠更狠的遮挡。下一课把单边拍卖换成买卖双方同时叫价。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>赢家诅咒改信念；全支付改的是「输家也付钱」。</li><li>完全信息对称：混合，\\([0,v]\\) 上均匀，租金耗尽。</li><li>非对称可降低总耗散；公平不一定提高努力。</li><li>与消耗战同构，与一价只赢家付款不同。</li><li>出处：Baye, Kovenock and de Vries, <em>AER</em> 1993；<em>Economic Theory</em> 1996。</li></ul>',14))])}const v=n(c,[["render",B]]);export{f as __pageData,v as default};
